def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    return float(v)

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    spheres = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x
            spheres += x * r * r * r
    if total <= 0:
        return 0.0
    return float(4.0 * math.pi * spheres / (3.0 * total * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    electrons = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z):
            total += x
            electrons += x * z
    if total <= 0:
        return 0.0
    return float(electrons / (total * v))

def feature(s):
    props = s.get('element_properties', {})
    elements = [e for e, x in s.get('composition', {}).items() if x is not None and x > 0]
    best = math.inf
    for donor in elements:
        ion = props.get(donor, {}).get('first_ionization_energy_eV')
        if ion is None or not math.isfinite(ion):
            continue
        for acceptor in elements:
            if donor == acceptor and len(elements) > 1:
                continue
            affinity = props.get(acceptor, {}).get('electron_affinity_eV')
            if affinity is not None and math.isfinite(affinity):
                best = min(best, ion - affinity)
    return float(best) if math.isfinite(best) else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(p.get('occupancy', 1.0) or 0.0)) for p in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', []):
        d = b.get('distance_A')
        i = b['i']
        j = b['j']
        if d is not None and math.isfinite(d) and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    total = sum(occ[i] for i in range(n) if math.isfinite(nearest[i]))
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / total
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (nearest[i] - mean) ** 2 for i in range(n) if math.isfinite(nearest[i])) / total
    return float(math.sqrt(max(0.0, variance)) / mean)
